        H("Bala A281180 Totient-Square Period"),
        Blocks(
            Node("BalaFlow.flow", "flow", Formula0(),
                "The existing factorial-scaled encoder sends the integer values of iterated derivations to a rational exponential generating series.", DescribeRole.Definition, AssessedProvenance.FromRepo()),
            Node("BalaFlow.eCoeff_flow", "eCoeff flow", Formula1(),
